/* Editable reference footer, independent from product and header settings. */
(() => {
const suppliedBreakfastPhoto='data:image/jpeg;base64,';
const suppliedFamilyPhoto='data:image/jpeg;base64,';
const suppliedMeatPhoto='data:image/jpeg;base64,';
const suppliedFruitPhoto='data:image/jpeg;base64,';
const suppliedPix='data:image/png;base64,';
const suppliedPicpay='data:image/png;base64,';
const previousPicpay='data:image/png;base64,';
const suppliedStoresRibbon='data:image/png;base64,';
const suppliedFooterLogo='data:image/png;base64,';
const previousFooterLogo='data:image/png;base64,';
function footerData(){if(!state.referenceFooter)state.referenceFooter={storesTitle:'Nossas Lojas',addressTitle:'Ofertas válidas apenas para os endereços abaixo:',paymentTitle:'NOVAS FORMAS DE PAGAMENTOS:',payments:'Pix · PicPay',paymentLogo:'',green:'#006738',red:'#a20b10',yellow:'#ffe338',stock:'OU ENQUANTO DURAREM NOSSOS ESTOQUES',stores:[{name:'SANTA CRUZ DA SERRA',city:'DUQUE DE CAXIAS',address:'AV. 31 DE MARÇO, 131',contact:'PARQUE PAULISTA · PAULISTA'},{name:'NOVA CAMPINAS',city:'DUQUE DE CAXIAS',address:'RUA 13, LOTES 24 E 26 QUADRA 75 · BOX 1 A 5',contact:'(21) 3900-3977'},{name:'JARDIM ANHANGÁ',city:'DUQUE DE CAXIAS',address:'AV. HÉLIO DE OLIVEIRA, Nº 116',contact:''}],campaigns:[{days:'QUARTA DA',title:'FEIRINHA',color:'#709929',image:''},{days:'QUINTA DA',title:'CARNE',color:'#ad151a',image:''},{days:'SEX/SÁB/DOM',title:'FAMÍLIA',color:'#008ab8',image:''},{days:'SEG E TER',title:'GOSTOSA',color:'#b60068',image:''}]};if((state.referenceFooter.logo===undefined||state.referenceFooter.logo===previousFooterLogo))state.referenceFooter.logo=suppliedFooterLogo;if(state.referenceFooter.storesImage===undefined)state.referenceFooter.storesImage=suppliedStoresRibbon;if(state.referenceFooter.pixLogo===undefined)state.referenceFooter.pixLogo=suppliedPix;if((state.referenceFooter.picpayLogo===undefined||state.referenceFooter.picpayLogo===previousPicpay))state.referenceFooter.picpayLogo=suppliedPicpay;if(!state.referenceFooter.ribbonTextVersion){state.referenceFooter.storesImage='';state.referenceFooter.ribbonTextVersion=1;}if(!state.referenceFooter.fruitPhotoVersion){state.referenceFooter.campaigns[0].image=suppliedFruitPhoto;state.referenceFooter.fruitPhotoVersion=1;}if(!state.referenceFooter.meatPhotoVersion){state.referenceFooter.campaigns[1].image=suppliedMeatPhoto;state.referenceFooter.meatPhotoVersion=1;}if(!state.referenceFooter.familyPhotoVersion){state.referenceFooter.campaigns[2].image=suppliedFamilyPhoto;state.referenceFooter.familyPhotoVersion=1;}if(!state.referenceFooter.breakfastPhotoVersion){state.referenceFooter.campaigns[3].image=suppliedBreakfastPhoto;state.referenceFooter.breakfastPhotoVersion=1;}return state.referenceFooter}
const color=(s,f)=>/^#[a-f0-9]{6}$/i.test(s)?s:f;
const img=s=>/^data:image\/(png|jpeg|webp);base64,/.test(s||'')?s:'';
function pathGet(path){return path.split('.').reduce((o,k)=>o[k],footerData())}
function pathSet(path,value){const keys=path.split('.');let o=footerData();for(const k of keys.slice(0,-1))o=o[k];o[keys.at(-1)]=value}
const oldFlyer=flyerHTML;
flyerHTML=function(pg,interactive=true){const template=document.createElement('template');template.innerHTML=oldFlyer(pg,interactive);const f=template.content.querySelector('.flyer-footer');if(!f)return template.innerHTML;const d=footerData();f.className='flyer-footer reference-footer';f.style.cssText=`--footer-green:${color(d.green,'#006738')};--footer-red:${color(d.red,'#a20b10')};--footer-yellow:${color(d.yellow,'#ffe338')}`;if(interactive)f.dataset.design='brand';f.innerHTML=`<div class="ref-footer-top"><div class="ref-footer-logo">${img(d.logo)?`<img src="${esc(d.logo)}" alt="${esc(state.brand)}">`:`<strong>${esc(state.brand)}</strong>`}</div><div class="ref-stores-ribbon ${img(d.storesImage)?'has-image':''}">${img(d.storesImage)?`<img src="${esc(d.storesImage)}" alt="${esc(d.storesTitle)}">`:`<span>${esc(d.storesTitle)}</span>`}</div><div class="ref-payments"><b>${esc(d.paymentTitle)}</b>${img(d.paymentLogo)?`<img src="${esc(d.paymentLogo)}" alt="${esc(d.payments)}">`:`<div class="ref-payment-logos">${img(d.pixLogo)?`<img src="${esc(d.pixLogo)}" alt="Pix">`:``}${img(d.picpayLogo)?`<img src="${esc(d.picpayLogo)}" alt="PicPay">`:``}${!img(d.pixLogo)&&!img(d.picpayLogo)?`<span>${esc(d.payments)}</span>`:``}</div>`}</div></div><div class="ref-footer-main"><div class="ref-addresses"><h4>${esc(d.addressTitle)}</h4><div class="ref-store-grid">${d.stores.map(s=>`<div class="ref-store"><strong>${esc(s.name)}</strong><b>${esc(s.city)}</b><p>${esc(s.address)}</p><p>${esc(s.contact)}</p></div>`).join('')}</div></div><div class="ref-events"><div class="ref-validity"><span>OFERTAS VÁLIDAS DE</span><b>${esc(date(state.start))} a ${esc(date(state.end))}</b><span>${esc(d.stock)}</span></div><div class="ref-campaigns">${d.campaigns.map((c,i)=>`<div class="ref-campaign" style="background:${color(c.color,'#008ab8')}"><span>${esc(c.days)}</span><strong>${esc(c.title)}</strong>${img(c.image)?`<img src="${esc(c.image)}" alt="${esc(c.title)}">`:`<div class="ref-campaign-empty">${interactive?'Enviar imagem em Identidade':''}</div>`}</div>`).join('')}</div></div></div><div class="ref-footer-legal">${esc(state.legal)}${state.products.slice(pg*30,pg*30+30).some(p=>p.imageSource)?' · Fotos: Open Food Facts, CC BY-SA 3.0. Fontes nos produtos.':''}</div>`;return template.innerHTML};
const input=(key,label,type='text')=>`<label>${label}<input type="${type}" data-footer-field="${key}" value="${esc(pathGet(key))}" maxlength="250"></label>`;
const upload=(key,label)=>`<label class="button">Enviar ${label}<input hidden type="file" accept="image/*" data-footer-image="${key}"></label>${pathGet(key)?`<button class="text-button" data-footer-remove="${key}">Remover imagem</button>`:''}`;
const oldFields=renderFields;
renderFields=function(){oldFields();if(tab!=='brand')return;const d=footerData();$('#brandFields').insertAdjacentHTML('afterbegin',`<details class="design-controls"><summary><strong>Rodapé — lojas, pagamentos e campanhas</strong></summary><p class="help">Exibido nas páginas com rodapé ativado. O nome da marca usa os campos da loja; o logotipo pode ser trocado abaixo; a validade usa as datas em Edição; o texto legal usa Condições das ofertas.</p>${upload('logo','logotipo do rodapé')}${input('storesTitle','Título da faixa de lojas')}${upload('storesImage','faixa Nossas Lojas')}${input('addressTitle','Frase acima dos endereços')}${input('paymentTitle','Título dos pagamentos')}${input('payments','Formas de pagamento')}${upload('paymentLogo','faixa completa de pagamentos')}${upload('pixLogo','logo Pix')}${upload('picpayLogo','logo PicPay')}<div class="two-cols">${input('green','Fundo principal','color')}${input('red','Faixa inferior','color')}${input('yellow','Destaques','color')}</div>${input('stock','Condição da validade')}${d.stores.map((s,i)=>`<details><summary>Loja ${i+1}</summary>${input('stores.'+i+'.name','Bairro / nome da loja')}${input('stores.'+i+'.city','Cidade')}${input('stores.'+i+'.address','Endereço')}${input('stores.'+i+'.contact','Contato / complemento')}</details>`).join('')}${d.campaigns.map((c,i)=>`<details><summary>Campanha ${i+1} — ${esc(c.title)}</summary>${input('campaigns.'+i+'.days','Dias / chamada')}${input('campaigns.'+i+'.title','Título')}${input('campaigns.'+i+'.color','Cor de fundo','color')}${upload('campaigns.'+i+'.image','foto da campanha')}</details>`).join('')}</details>`)};
document.addEventListener('input',e=>{const path=e.target.dataset.footerField;if(!path)return;pathSet(path,e.target.value);persist();render()});
document.addEventListener('change',async e=>{const path=e.target.dataset.footerImage;if(!path)return;try{pathSet(path,await readImage(e.target.files[0],900));persist();render();renderFields()}catch(err){toast(err.message)}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-footer-remove]');if(b){pathSet(b.dataset.footerRemove,'');persist();render();renderFields()}});
render();
})();
